--- a/Sources/Clinic/PetPhotoLoader.swift
+++ b/Sources/Clinic/PetPhotoLoader.swift
@@ -8,16 +8,30 @@ final class PetPhotoLoader: ObservableObject {

     @Published var image: UIImage?
     @Published var isLoading = false

     private let session: URLSession

-    func load(_ url: URL) {
-        isLoading = true
+    func load(_ url: URL) {
+        isLoading = true
+
+        session.dataTask(with: url) { data, _, _ in
+            guard let data, let loaded = UIImage(data: data) else {
+                return
+            }
+
+            self.image = loaded
+
+            DispatchQueue.main.async {
+                self.isLoading = false
+            }
+        }
+        .resume()
     }

     func reset() {
         image = nil
         isLoading = false
     }
 }
